function bodySVG(side, sets) {
  // sets: Map muscle -> sets this week. 1-5 = light green, 6+ = bright green.
  const lvl = (m) => { const n = sets.get(m) || 0; return n >= 6 ? " hit" : n > 0 ? " hit-lo" : ""; };
  const draw = () => app.BODY[side].map((p) => {
    if (p.m === "base") return `<path class="base" d="${p.d}"/>`;
    return p.m ? `<path class="mus${lvl(p.m)}" data-m="${p.m}" d="${p.d}"/>` : `<path class="skin" d="${p.d}"/>`;
  }).join("");
  const mid = side === "front" ? `<path class="line" d="M100,119 L100,216"/>` : `<path class="line" d="M100,50 L100,230"/>`;
  return `<svg viewBox="2 6 196 404" class="body" role="img" aria-label="${side === "front" ? "Front" : "Back"} of body">
    <g>${draw()}</g><g transform="translate(200,0) scale(-1,1)">${draw()}</g>
    <path class="detail" d="${app.BODY_DETAIL[side]}"/><path class="detail" transform="translate(200,0) scale(-1,1)" d="${app.BODY_DETAIL[side]}"/>
    ${mid}<path class="skin" d="${app.BODY_HEAD}"/></svg>`;
}
app.bodySVG = bodySVG;
